        $end = new DateTime($endDate);
        $interval = new DateInterval('P1D'); // 1 day interval
        $period = new DatePeriod($start, $interval, $end);
        $weekendDays = 0;
        foreach ($period as $date) {
            $dayOfWeek = $date->format('N'); // 1 (Monday) through 7 (Sunday)
