User: write me a program in nodejs with express and ejs. i want it to recursively scan a directory, and serve a nested list of files and folders as a webpage
Assistant: Here's a simple Node.js program using Express and EJS that recursively scans a directory and serves a nested list of files and folders as a webpage:

1. First, install the necessary packages:
```bash
npm init -y
npm install express ejs
```

2. Create the main application file app.js:

```
const express = require('express');
const app = express();
const ejs = require('ejs');
const path = require('path');
const fs = require('fs');

// Set the views directory and the view engine
app.set('views', path.join(__dirname, 'views'));
app.set('view engine', 'ejs');

// Define the route for the directory listing
app.get('/list/:dir(*)', (req, res) => {
  const dirPath = path.join(__dirname, req.params.dir);
  if (fs.existsSync(dirPath)) {
    const listData = getNestedList(dirPath);
    res.render('list', { dirPath, listData });
  } else {
    res.status(404).send('Directory not found');
  }
});

// Define the function to recursively get the nested list of a directory
function getNestedList(dirPath) {
  const files = fs.readdirSync(dirPath);
  const nestedList = [];
  files.forEach(file => {
    const filePath = path.join(dirPath, file);
    if (fs.statSync(filePath).isDirectory()) {
      const subList = getNestedList(filePath);
